draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // couple
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20*Math.sin(t), H/2 - 20, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2 - 20, 20, 0, 2*Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2 - 20 + 20);
  ctx.lineTo(W/2 - 50 + 20*Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.cos(t), H/2 - 20 + 20);
  ctx.lineTo(W/2 + 50 + 20*Math.cos(t), H/2 + 50);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2 - 20 + 40);
  ctx.lineTo(W/2 - 80 + 20*Math.sin(t), H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.cos(t), H/2 - 20 + 40);
  ctx.lineTo(W/2 + 80 + 20*Math.cos(t), H/2 + 20);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2 - 20 + 20);
  ctx.lineTo(W/2 + 50 + 20*Math.cos(t), H/2 - 20 + 20);
  ctx.stroke();

  ctx.restore();
}
